// Generated by npm run build. Edit scripts/service-worker.template.js instead.
"use strict";
const VERSION = "__CACHE_VERSION__";
const ROOT = new URL(self.registration.scope);
// Cache Storageは同一オリジンの他作品と共有されるので、公開パスごとに分離する。
const PREFIX = `pentamond:${ROOT.pathname}:`;
const CACHE = `${PREFIX}${VERSION}`;
const ASSETS = __PRECACHE_URLS__;
const URLS = new Set(ASSETS.map((path) => new URL(path, ROOT).href));
const INDEX = new URL("index.html", ROOT).href;

self.addEventListener("install", (event) => {
    event.waitUntil((async () => {
        const cache = await caches.open(CACHE);
        const pending = [...URLS];
        let failed;
        // 同時通信数を抑え、音源を含むリリース一式が揃った時だけインストール成功とする。
        await Promise.all(Array.from({ length: 4 }, async () => {
            while (pending.length && !failed) {
                const url = pending.shift();
                try {
                    const response = await fetch(new Request(url, { cache: "reload" }));
                    if (!response.ok || response.redirected) throw new Error(`PWA asset: ${url} (${response.status})`);
                    await cache.put(url, response);
                } catch (error) { failed = error; }
            }
        }));
        if (failed) {
            await caches.delete(CACHE);
            throw failed;
        }
        // skipWaitingしない。プレイ中のタブが残っている間は旧版を維持する。
    })());
});

self.addEventListener("activate", (event) => {
    event.waitUntil((async () => {
        const names = await caches.keys();
        await Promise.all(names.filter((name) => name.startsWith(PREFIX) && name !== CACHE).map((name) => caches.delete(name)));
        // clients.claimや強制リロードは行わず、次の起動から新しい一式を使う。
    })());
});

self.addEventListener("fetch", (event) => {
    const request = event.request;
    if (request.method !== "GET") return;
    const url = new URL(request.url);
    if (url.origin !== ROOT.origin || !url.pathname.startsWith(ROOT.pathname)) return;
    url.hash = "";
    url.search = "";
    let key = url.href;
    if (request.mode === "navigate" && (key === ROOT.href || key === INDEX)) key = INDEX;
    if (!URLS.has(key)) return;
    event.respondWith((async () => {
        const cache = await caches.open(CACHE);
        // HTML・JS・CSS・音源を同じ版に固定して、更新途中の混在を避ける。
        const cached = await cache.match(key);
        return cached || fetch(request);
    })());
});
